// Generated by the Niobium FHE Application Design AI Assistant (FHEanna).
//
// Compatibility check: the WebAssembly patient side against the native server.
// keygen + encrypt in WebAssembly -> files -> native health_risk_server -> decrypt
// in WebAssembly, for a few test patients, compared with the reference answers.
//
// Usage: node web/test_roundtrip.mjs [--cpu|--sim]   (from examples/health_risk/)

import { execFileSync } from "node:child_process";
import fs from "node:fs";
import path from "node:path";
import { fileURLToPath } from "node:url";
import createRiskClient from "./static/risk_client.js";

const WEB = path.dirname(fileURLToPath(import.meta.url));
const APP = path.dirname(WEB);
const REPO = path.resolve(APP, "../..");
const mode = process.argv[2] ?? "--cpu";
const home = path.join(APP, "run_wasm", "server_home");
fs.rmSync(path.dirname(home), { recursive: true, force: true });
fs.mkdirSync(home, { recursive: true });

const m = await createRiskClient();
let t = Date.now();
m.keygen(65536);
console.log(`wasm keygen: ${((Date.now() - t) / 1000).toFixed(1)}s`);
for (const name of ["cc.bin", "pk.bin", "mk.bin", "rk.bin"]) {
  const b = m.setupFile(name);
  fs.writeFileSync(path.join(home, name), b);
  console.log(`  ${name}: ${b.length.toLocaleString()} bytes`);
}
fs.copyFileSync(path.join(APP, "data", "model.txt"), path.join(home, "model.txt"));

const rows = fs.readFileSync(path.join(APP, "data", "test_patients.csv"), "utf8").trim().split("\n").slice(1);
const picks = [0, 1, 2, 5001, 5128].map((i) => rows[i].split(","));
const env = { ...process.env, NBCC_FHETCH_SIM: path.join(REPO, "build/vendor/niobium-fhetch/fhetch_sim") };
const server = path.join(REPO, "build/examples/health_risk_server");
let worst = 0;
for (const r of picks) {
  const [sex, age, bmi, sbp, trt, smk, dia, ref, twin] = r;
  const args = [sex === "male", +age, +bmi, +sbp, +trt, +smk, +dia];
  t = Date.now();
  fs.writeFileSync(path.join(home, "ct_x.bin"), m.encrypt(...args));
  const te = Date.now() - t;
  const flags = mode === "--cpu" ? ["--cpu"] : ["--hollow"];
  execFileSync(server, [".", ...flags], { cwd: home, env, stdio: "ignore" });
  t = Date.now();
  const risk = m.decrypt(fs.readFileSync(path.join(home, "ct_result.bin")));
  const td = Date.now() - t;
  const err = Math.abs(risk - +twin);
  worst = Math.max(worst, err);
  console.log(`  ${sex} ${age} ${bmi} ${sbp} t${trt} s${smk} d${dia}: ${(risk * 100).toFixed(4)}%` +
    `  reference ${(+ref * 100).toFixed(4)}%  |wasm-native - twin| ${(err * 100).toExponential(2)} pp` +
    `  (encrypt ${te} ms, decrypt ${td} ms)`);
}
console.log(worst <= 1e-5 ? "PASS" : "FAIL", `worst ${(worst * 100).toExponential(2)} pp (tolerance 1e-3 pp)`);
process.exit(worst <= 1e-5 ? 0 : 1);
